// 正常安装目录与NativeRequest上的本人随行链；新ABI就绪前只编译，不以组件或手填初态冒正式入口。
#include "resident/kernel/boundary_dispatch.hpp"
#include "resident/storage/common_codec.hpp"
#include <algorithm>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
using V=BoundaryValue;namespace fs=std::filesystem;int checks=0;V::Array trace;
// 即使Release也记录每个边界；首次拒绝立即保原回执和已发生轨迹。
void check(bool value,const StableId& why){++checks;if(!value)throw std::runtime_error(why);}
template<class T>T need(Outcome<T> value,const StableId& why){check(value.ok,why+": "+value.error.original.code);return std::move(value.value);}
const V& field(const V& value,const StableId& key){return boundary::field(value,key,"probe");}
StableId text(const V& value,const StableId& key){return boundary::get_string(value,key,"probe");}
StableId json(const V& value){return need(render_boundary_json(value),"render evidence");}
bool okay(const V& value){auto p=value.find("ok");return p&&p->as<bool>()&&*p->as<bool>();}
V read(const fs::path& path){std::ifstream in(path);check(bool(in),"open input");std::ostringstream data;data<<in.rdbuf();return need(parse_boundary_json(data.str()),"parse input");}
void write(const fs::path& path,const V& value){std::ofstream out(path);check(bool(out),"open evidence");out<<json(value)<<'\n';}
// 热命令和报价均取原当前command_context；不能从oracle补造权限。
V query(ResidentReplaySession& world,const StableId& id,const V& args=boundary::obj({})){LiveOperation op;op.source=need(world.identity(),"query source");op.payload=boundary::obj({{"query_id",V{id}},{"args",args}});return need(world.execute_live(op),"query "+id).result;}
V preview(ResidentReplaySession& world,const StableId& kind,const V& params){LiveOperation op;op.kind=LiveOperationKind::preview;op.source=need(world.identity(),"preview source");op.payload=boundary::obj({{"kind",V{kind}},{"params",params},{"actor_id",field(query(world,"command_context"),"actor_id")}});return need(world.execute_live(op),"preview "+kind).result;}
V submit(ResidentReplaySession& world,const StableId& kind,const V& params){auto context=query(world,"command_context");LiveOperation op;op.kind=LiveOperationKind::command;op.source=need(world.identity(),"submit source");op.payload=boundary::obj({{"kind",V{kind}},{"params",params},{"actor_id",field(context,"actor_id")},{"request_seq",field(context,"next_request_seq")},{"expected_revision",field(context,"revision")}});auto result=need(world.execute_live(op),"submit "+kind).result;trace.push_back(boundary::obj({{"command",op.payload},{"receipt",result}}));check(okay(result),"refused "+kind+": "+json(result));return result;}
V exported(ResidentReplaySession& world){return need(world.export_state(),"export oracle");}
// 只对实际已公开的当场人物topic发起会面；不枚举远方作者岗位。
void meet(ResidentReplaySession& world){auto sidebar=query(world,"place_sidebar");V selected;for(const auto& person:boundary::array(field(sidebar,"people"),"people")){if(text(person,"actor_id")!="society::actor.study_caravanner")continue;for(const auto& topic:boundary::array(field(person,"topics"),"topics"))if(text(topic,"role_id")=="contacts::role.follow_caravanner"&&boundary::get_bool(topic,"available","topic"))selected=boundary::obj({{"role_id",field(topic,"role_id")}});}check(selected.find("role_id"),"no real present invitation topic: "+json(sidebar));check(okay(preview(world,"talk",selected)),"actual invitation talk quote refused");submit(world,"talk",selected);for(int n=0;n<4;++n){auto view=query(world,"interaction_view");if(text(view,"phase")=="choice")return;check(text(view,"phase")=="say","unexpected invitation phase");submit(world,"dialogue_next",boundary::obj({}));}throw std::runtime_error("invitation dialogue bound");}
// 页中原参数是本人操作唯一来源；同源预览仍是最终可办理判定。
V action(ResidentReplaySession& world,const StableId& kind){const auto page=query(world,"party_participation");for(const auto& row:boundary::array(field(page,"rows"),"rows"))for(const auto& item:boundary::array(field(row,"actions"),"actions"))if(text(item,"command")==kind){check(boundary::get_bool(item,"available","action"),"page action blocked: "+json(item));check(okay(preview(world,kind,field(item,"params"))),"original page quote blocked: "+kind);return field(item,"params");}throw std::runtime_error("missing current party action "+kind);}
Bytes save(ResidentReplaySession& world,const fs::path& root,const StableId& name){auto bytes=need(world.checkpoint(),"checkpoint");std::ofstream out(root/(name+".bank"),std::ios::binary);check(bool(out),"bank open");out.write(reinterpret_cast<const char*>(bytes.data()),bytes.size());check(bool(out),"bank write");write(root/(name+".json"),exported(world));write(root/(name+"-page.json"),query(world,"party_participation"));return bytes;}
std::unique_ptr<ResidentReplaySession> cold(const V& catalog,const Bytes& bytes){auto result=create_resident_replay_session();auto restored=result->initialize_checkpoint(catalog,bytes);check(restored.ok,"real bank restore: "+restored.error.original.code);check(bytes==need(result->checkpoint(),"cold exact checkpoint"),"cold bytes changed");return result;}
// 仅比较这些命令约定不会触及的真实钱物/行动/关系；外层回执编号不冒充领域副作用。
void unchanged(const V& before,const V& after){for(const auto* key:{"tick","wallets","inventories","actions","facts","relations","rng"})check(compare_boundary(field(before,key),field(after,key)).exact(),StableId{"unexpected side effect: "}+key);}
}
int main(int argc,char** argv){fs::path root;try{
    check(argc==4,"usage: party_invitation_live_probe CATALOG NATIVE_REQUEST OUTPUT");root=argv[3];fs::create_directories(root);const auto catalog=read(argv[1]),request=read(argv[2]);check(text(request,"scenario_id")=="contacts::scenario.qingchuan_following","normal following scenario required");auto missing_marker=request;auto& requested_modules=*missing_marker.find("expected_catalog_identity")->find("module_versions")->as<V::Array>();requested_modules.erase(std::remove_if(requested_modules.begin(),requested_modules.end(),[](const V& value){return text(value,"name")=="party_invitations";}),requested_modules.end());auto denied=create_resident_replay_session();auto bad_admission=denied->initialize_native(catalog,missing_marker);check(!bad_admission.ok&&bad_admission.error.original.code=="NativeCatalogIdentityMismatch","actual admission accepted missing party marker");auto world=create_resident_replay_session();auto initialized=world->initialize_native(catalog,request);check(initialized.ok,"normal native initialization: "+initialized.error.original.code);
    // 检查点选取口仅供尚未安装的Session；目录身份按typed值与模块数组顺序比较，字典展示顺序不是权限。
    auto initial=need(world->checkpoint(),"initial bank");auto inspector=create_resident_replay_session();auto selection=need(inspector->inspect_checkpoint_selection(initial),"actual admitted identity through uninstalled inspector");check(compare_boundary(field(selection,"catalog"),field(request,"expected_catalog_identity")).values_equal,"loader request and actual admitted modules differ");int markers=0;for(const auto& item:boundary::array(field(field(selection,"catalog"),"module_versions"),"modules"))if(text(item,"name")=="party_invitations"){++markers;check(text(item,"version")=="1","wrong party module version");}check(markers==1,"party marker missing or duplicated");write(root/"admitted-selection.json",selection);
    auto unknown=query(*world,"party_participation");check(boundary::array(field(unknown,"rows"),"rows").empty(),"unseen author invitation leaked");auto q1=preview(*world,"party_accept",boundary::obj({{"invitation_id",V{"contacts::invitation.caravanner"}}}));auto q2=preview(*world,"party_accept",boundary::obj({{"invitation_id",V{"contacts::invitation.absent"}}}));check(!okay(q1)&&!okay(q2)&&text(q1,"code")==text(q2,"code"),"unknown invitation privacy differs");check(initial==need(world->checkpoint(),"pure unknown page"),"unknown reads changed world");
    meet(*world);auto before=exported(*world);submit(*world,"dialogue_choose",boundary::obj({{"option_id",V{"decline"}}}));submit(*world,"dialogue_next",boundary::obj({}));auto declined=exported(*world);unchanged(before,declined);check(compare_boundary(field(before,"parties"),field(declined,"parties")).exact(),"ordinary refusal altered party");save(*world,root,"declined");meet(*world);
    auto interaction=query(*world,"interaction_view");auto reverse=preview(*world,"join_party",boundary::obj({{"actor_id",V{"society::actor.study_caravanner"}},{"context",field(interaction,"context")}}));check(!okay(reverse)&&text(reverse,"code")=="PartyInvitationAcceptanceRequired","dedicated invitation role permitted reverse recruitment");write(root/"reverse-recruitment-preview.json",reverse);save(*world,root,"invited");before=exported(*world);submit(*world,"party_accept",action(*world,"party_accept"));auto joined=exported(*world);unchanged(before,joined);const auto& actor=field(field(joined,"actors"),"society::actor.apprentice");check(text(field(actor,"location"),"kind")=="Following","accept did not create real following");const auto party_id=text(field(actor,"location"),"party_id");const auto& party=field(field(joined,"parties"),party_id);check(text(party,"leader_id")=="society::actor.study_caravanner","wrong party direction");check(boundary::get_int(field(field(party,"terms"),"society::actor.apprentice"),"cost_per_tick","terms")==6,"actual party lost original authored fee");auto accepted=save(*world,root,"accepted");auto forbidden=preview(*world,"move_local",boundary::obj({{"place_id",V{"society::place.school"}}}));check(!okay(forbidden)&&text(forbidden,"code")=="NotPartyLeader","following guard permitted own route movement");check(accepted==need(world->checkpoint(),"after forbidden following movement"),"rejected member movement changed world");auto restored=cold(catalog,accepted);check(compare_boundary(query(*world,"party_participation"),query(*restored,"party_participation")).exact(),"cold member page differs");
    auto repeated=preview(*world,"party_accept",boundary::obj({{"invitation_id",V{"contacts::invitation.caravanner"}}}));check(!okay(repeated),"duplicate invitation accepted twice");submit(*world,"end_interaction",action(*world,"end_interaction"));auto closed=save(*world,root,"member-closed");const auto before_leave=exported(*world);submit(*world,"party_leave",action(*world,"party_leave"));auto left=exported(*world);unchanged(before_leave,left);check(text(field(field(field(left,"actors"),"society::actor.apprentice"),"location"),"kind")=="Settlement","own leave did not restore actual stopped place");check(!field(left,"parties").find(party_id),"last member left duplicate party");save(*world,root,"left");
    // 同一自然member银行分支只推进原世界半日；领队是否出发由真实Director决定。
    auto waiting=cold(catalog,closed);auto start=need(waiting->identity(),"before actual wait");auto wait_before=exported(*waiting);submit(*waiting,"wait",action(*waiting,"wait"));check(need(waiting->identity(),"after actual wait").tick==start.tick+1,"following wait did not advance one world halfday");auto wait_after=exported(*waiting);for(const auto& item:boundary::object(field(wait_after,"actions"),"actions"))check(!(text(item.second,"actor_id")=="society::actor.apprentice"&&text(item.second,"kind")=="wait"),"following wait created a second private action");save(*waiting,root,"after-wait");write(root/"actual-wait-effects.json",boundary::obj({{"before",wait_before},{"after",wait_after}}));
    write(root/"commands.json",V{trace});write(root/"result.json",boundary::obj({{"ok",V{true}},{"checks",V{Integer{checks}}},{"formal_native_request_and_admitted",V{true}},{"forced_leader_travel",V{false}},{"main_tested",V{false}}}));std::cout<<"party invitation live: "<<checks<<" checks 0 failures; real invitation/refusal/accept/member wait/leave/cold\n";return 0;
}catch(const std::exception& error){if(!root.empty()){write(root/"failed-commands.json",V{trace});write(root/"failure.json",boundary::obj({{"ok",V{false}},{"checks",V{Integer{checks}}},{"error",V{StableId(error.what())}}}));}std::cerr<<error.what()<<'\n';return 1;}}
